(function (root) {
  'use strict';
  const colors = ['빨강', '파랑', '초록', '노랑'], levels = { easy: '초급', normal: '중급', hard: '고급' };
  function tile(C, id) { const c = C.card(id); return `<span class="chain-card color-${c.color}"><b>${c.number}</b><small>${colors[c.color]}</small></span>`; }
  function banner(s, C) {
    if (s.status === 'playing') return '';
    const r = C.result(s), heading = s.game === 'chain' ? (s.status === 'completed' ? '열두 번의 연쇄를 완성했어요!' : '더 놓을 카드가 없어요.') : s.status === 'won' ? '승리했어요!' : s.status === 'draw' ? '무승부입니다.' : 'AI가 승리했어요.';
    return `<div class="result-band ${s.status === 'lost' ? 'failed' : ''}"><h2 id="phase-heading" tabindex="-1">${heading}</h2><p class="result-value">${s.game === 'chain' ? `${r.score}점 · ${r.stars ? '★'.repeat(r.stars) : '별 없음'}` : `나 ${r.humanPoints} : ${r.aiPoints} AI`}</p><p>${s.game === 'chain' ? `${r.turns}/12회 배치` : `${levels[r.difficulty]} · ${r.starter === 'human' ? '내 선공' : 'AI 선공'} · 중앙 보너스 포함`}</p><div class="result-actions"><button class="primary" data-new>새 도전</button><button data-records>내 기록</button><a class="button" href="index.html#games">게임 목록</a></div></div>`;
  }
  function chain(s, selected, C) {
    const d = s.data, playing = s.status === 'playing', actions = C.legalActions(s), can = side => actions.some(a => a.type === 'place' && a.index === selected && a.side === side);
    const blocked = playing && !actions.some(a => a.type === 'place');
    return `${banner(s, C)}${playing ? '<h2 id="phase-heading" tabindex="-1" class="visually-hidden">숫자 연쇄 배치</h2>' : ''}<div class="play-status"><span>배치 <strong>${d.turns}<small> / 12</small></strong></span><span>점수 <strong>${d.score}<small>점</small></strong></span><span>재추첨 <strong>${d.redraws}<small> / 2</small></strong></span></div><p class="short-rule">같은 색 또는 숫자 차이 1 · 카드를 고른 뒤 왼쪽/오른쪽에 놓으세요.</p><div class="chain-ends"><section><h3>왼쪽 끝</h3>${tile(C, d.chain[0])}<button data-chain-side="left" ${can('left') ? '' : 'disabled'}>← 왼쪽에 놓기</button></section><section><h3>오른쪽 끝</h3>${tile(C, d.chain.at(-1))}<button data-chain-side="right" ${can('right') ? '' : 'disabled'}>오른쪽에 놓기 →</button></section></div><h3 class="offer-title">${playing ? '연결할 카드 선택' : '남은 공개 카드'}</h3><div class="chain-offer">${d.offer.map((id, index) => { const possible = actions.some(a => a.type === 'place' && a.index === index); return `<button data-chain-card="${index}" aria-label="${colors[C.card(id).color]} ${C.card(id).number} 선택" aria-pressed="${index === selected}" ${playing && possible ? '' : 'disabled'}>${tile(C, id)}<small>${possible ? index === selected ? '선택됨' : '연결 가능' : '연결 불가'}</small></button>`; }).join('')}</div>${blocked ? '<p class="chain-blocked">양쪽 모두 막혔어요. 재추첨으로 계속할 수 있습니다. 배치 횟수는 줄지 않아요.</p>' : ''}<button data-chain-redraw ${actions.some(a => a.type === 'redraw') ? '' : 'disabled'}>공개 카드 재추첨 · ${d.redraws}회 남음</button><details class="chain-history"><summary>전체 카드줄 · ${d.chain.length}장</summary><div>${d.chain.map(id => tile(C, id)).join('')}</div></details><p class="note">배치 +2점 · 숫자 차이 1이면 추가 +1점 · 별 3개 30점 / 2개 20점</p>`;
  }
  function line(s, C) {
    const d = s.data, playing = s.status === 'playing', [h, a] = C.lineScore(d.board), highlighted = new Set(d.lastLines.flatMap(i => C.lineWindows[i])), last = d.moves.at(-1);
    return `<div class="light-settings"><label for="line-level">AI 난이도<select id="line-level">${Object.entries(levels).map(([id, label]) => `<option value="${id}" ${d.difficulty === id ? 'selected' : ''}>${label}</option>`).join('')}</select></label><label for="line-starter">선후공<select id="line-starter"><option value="human" ${d.starter === 'human' ? 'selected' : ''}>내가 먼저</option><option value="ai" ${d.starter === 'ai' ? 'selected' : ''}>AI가 먼저</option></select></label></div>${banner(s, C)}${playing ? '<h2 id="phase-heading" tabindex="-1" class="visually-hidden">라인 컨트롤 배치</h2>' : ''}<div class="play-status"><span>나 ● <strong>${h.linePoints + (playing ? 0 : h.center)}<small>점 · ${d.board.filter(n => n === 1).length}/10돌</small></strong></span><span>AI ◆ <strong>${a.linePoints + (playing ? 0 : a.center)}<small>점 · ${d.board.filter(n => n === 2).length}/10돌</small></strong></span></div><p class="line-turn" role="status">${playing ? d.turn === 1 ? '내 차례 · 빈칸에 돌 하나를 놓으세요.' : 'AI가 생각 중입니다…' : '20수 완료 · 중앙 보너스까지 합산했습니다.'}</p><div class="line-board" role="group" aria-label="5행 5열 라인 컨트롤 보드">${d.board.map((n, i) => `<button class="line-cell ${n === 1 ? 'human' : n === 2 ? 'ai' : ''} ${Math.floor(i / 5) >= 1 && Math.floor(i / 5) <= 3 && i % 5 >= 1 && i % 5 <= 3 ? 'central' : ''} ${highlighted.has(i) ? 'scored' : ''} ${i === last ? 'last-move' : ''}" data-line-cell="${i}" aria-label="${Math.floor(i / 5) + 1}행 ${i % 5 + 1}열 ${n === 1 ? '내 돌' : n === 2 ? 'AI 돌' : '빈칸'}" ${!playing || d.turn !== 1 || n ? 'disabled' : ''}>${n === 1 ? '●' : n === 2 ? '◆' : '<span aria-hidden="true">＋</span>'}</button>`).join('')}</div><p class="note">● 나 · ◆ AI · 연한 중앙 9칸은 종료 때 돌당 +1점</p><div class="line-details"><p>완성 구간: 나 ${h.lines.length}개 / AI ${a.lines.length}개 (각 +3점)</p><p>종료 시 중앙 보너스: 나 +${h.center} / AI +${a.center}</p>${d.lastLines.length ? `<p class="line-gain">방금 ${d.lastLines.length}구간 완성 · +${d.lastLines.length * 3}점</p>` : ''}</div>`;
  }
  root.SoloExtraUI = { render: (s, selected, C) => s.game === 'chain' ? chain(s, selected, C) : line(s, C), levels };
})(window);
